"""
Cost/latency recording for the planner and execution-agent components.

This is a thin adapter: it prices a planner/agent LLM call (reusing rlm_cost's
single price table) and forwards the result into the unified per-task metrics
(`task_metrics`), which writes ONE row per task across all components.

  - "planner" : the task planner LLM call in
                workflow_agent.build_query_with_next_steps
  - "agent"   : each ReAct tool-selection LLM call in fastWorkflowReAct.forward
                (the RLM recall cost is NOT counted here — it is recorded by
                rlm_cost.record_rlm_call under the "rlm" component)

Token usage is captured with dspy's native usage tracker
(`dspy.track_usage()`) wrapped around each component's LLM call by the caller.

Per-task attribution uses `run_id` (one ChatSession/SmartRetriever per task).
There is no separate component CSV anymore — see task_metrics.py.
"""
from __future__ import annotations

from fastworkflow.utils.rlm_logger import rlm_log
# Reuse the single pricing source so all components are priced identically.
from fastworkflow.rlm_cost import _compute_cost
from fastworkflow import task_metrics

_COMPONENTS = ("planner", "agent")


def record_component_call(run_id: str, component: str, usage_totals: dict,
                          duration_s: float) -> tuple[float, int, int]:
    """
    Price one planner or execution-agent LLM call and forward it to the unified
    per-task metrics.

    `run_id` is the per-task identity. `component` must be "planner" or "agent".
    `usage_totals` is the output of `dspy.UsageTracker.get_total_tokens()`:
    a map of model-name -> {prompt_tokens, completion_tokens, ...}.

    Returns (cost_usd, input_tokens, output_tokens). Metrics failures never
    propagate — they must not break the agent.
    """
    try:
        if component not in _COMPONENTS:
            rlm_log(f"[COMPONENT COST] ignoring unknown component '{component}'")
            return 0.0, 0, 0

        total_in = 0
        total_out = 0
        total_cost = 0.0
        for model, usage in (usage_totals or {}).items():
            in_tok = int((usage or {}).get("prompt_tokens", 0) or 0)
            out_tok = int((usage or {}).get("completion_tokens", 0) or 0)
            total_in += in_tok
            total_out += out_tok
            total_cost += _compute_cost(model, in_tok, out_tok)

        task_metrics.record(run_id, component, calls=1, input_tokens=total_in,
                           output_tokens=total_out, cost_usd=total_cost,
                           duration_s=duration_s)

        rlm_log(
            f"[COMPONENT COST] {component} (run={run_id}): in={total_in} "
            f"out={total_out} tokens, cost=${total_cost:.6f}, {duration_s:.2f}s"
        )
        return total_cost, total_in, total_out
    except Exception as e:  # metrics must never break the agent
        rlm_log(f"[COMPONENT COST] record_component_call failed: {e}")
        return 0.0, 0, 0
